"""Small pure functions."""


def add(a, b):
    return a + b


def mul(a, b):
    return a * b if b >= 0 else 0

import unittest

from mathlib import add, mul


class AddTest(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)

    def test_mul(self):
        self.assertEqual(mul(4, 3), 12)


if __name__ == "__main__":
    unittest.main()

